suppressPackageStartupMessages({library(SCpubr); library(Seurat); library(ggplot2)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
so <- readRDS("../_data/zeisel_seurat.rds"); mk <- c("Snap25","Gad1","Gad2","Pvalb","Sst","Satb2","Neurod6","Wfs1","Aqp4","Gfap","Mbp","Plp1","Cx3cr1","C1qa","Cldn5","Acta2")
sv <- function(f, p, w = 7, h = 6) if (inherits(p, "recordedplot")) { png(f, w*140, h*140, res = 140); replayPlot(p); dev.off() } else ggsave(f, p, width = w, height = h, dpi = 140, bg = "white")
sv("v1_do_DimPlot.png", do_DimPlot(so, label = TRUE, repel = TRUE, legend.position = "none", plot.title = "SCpubr::do_DimPlot"))
sv("v2_do_NebulosaPlot.png", do_NebulosaPlot(so, features = c("Gad1","Mbp"), joint = FALSE), 10, 5)
sv("v3_do_DotPlot.png", do_DotPlot(so, features = mk, flip = TRUE), 9, 5)
sv("v4_do_ChordDiagram.png", tryCatch(do_ChordDiagramPlot(so, from = "celltype", to = "tissue"), error = function(e) do_BarPlot(so, group.by = "celltype", split.by = "tissue", position = "fill", flip = TRUE)))
sv("v5_do_BoxPlot.png", do_BoxPlot(so, feature = "nFeature_RNA", group.by = "celltype"), 8, 5)
